/* @lc app=leetcode id=4067 lang=kotlin */ class Solution { fun maxSubarray(nums: IntArray): Int = IntArray(502).let { cnt -> nums.indices.fold(0 to 0) { (l0, best), i -> nums[i].let { x -> generateSequence(l0) { l -> if ((1..500).any { d -> cnt[d] > 0 && ((x - d in 1..500 && (if (x - d == d) cnt[d] >= 2 else cnt[x - d] > 0)) || (x + d <= 500 && cnt[x + d] > 0)) }) cnt.set(nums[l], cnt[nums[l]] - 1).let { l + 1 } else null }.last().let { l -> cnt.set(x, cnt[x] + 1).let { l to maxOf(best, i - l + 1) } } } }.second } }